// Mappe les lignes du template actif vers promotions_dji.
// Sortie : UN seul item portant toutes les lignes en JSON ($json.payload), que
// le node Postgres deplie avec jsonb_to_recordset en une seule requete.

// Date Excel (numero de serie) ou texte JJ/MM/AAAA / AAAA-MM-JJ -> 'AAAA-MM-JJ'
function toISODate(v) {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim();
  if (/^\d+(\.\d+)?$/.test(s)) {
    const d = new Date(Math.round((Math.floor(Number(s)) - 25569) * 86400 * 1000));
    return isNaN(d) ? null : d.toISOString().slice(0, 10);
  }
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  return null;
}
function parseNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(String(v).replace(',', '.').replace(/[^\d.-]/g, ''));
  return isNaN(n) ? null : n;
}
function cleanString(v) {
  if (v === null || v === undefined) return null;
  const c = String(v).trim();
  return c === '' ? null : c;
}
// Normalise un en-tete : retours ligne, espaces multiples, apostrophes, casse
const norm = s => String(s || '').replace(/[‘’]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase();
// Valeur de la premiere colonne dont l'en-tete vaut ou commence par l'un des alias
function col(row, ...aliases) {
  const keys = Object.keys(row);
  for (const a of aliases.map(norm)) {
    const k = keys.find(k => norm(k) === a) || keys.find(k => norm(k).startsWith(a));
    if (k !== undefined) return row[k];
  }
  return null;
}

const res = $input.first().json;
if (!res || res.success !== true || !Array.isArray(res.data)) {
  // On s'arrete AVANT toute ecriture : la table reste telle quelle.
  throw new Error('Reponse template invalide : ' + JSON.stringify(res).slice(0, 300));
}

// Cle = trio de l'index unique. Deux lignes du fichier sur la meme cle feraient
// echouer l'upsert ("ON CONFLICT DO UPDATE command cannot affect row a second
// time") : la derniere du fichier l'emporte.
const byKey = new Map();
const sansDateDebut = [];
let lignesLues = 0;

for (const row of res.data) {
  const produit = cleanString(col(row, 'Produit'));
  const reference = cleanString(col(row, 'Référence produit - STS'));
  if (!produit || !reference) continue;
  lignesLues++;

  const dateDebut = toISODate(col(row, 'Date de début'));
  if (!dateDebut) {
    sansDateDebut.push(reference);
    continue;
  }
  const dateFin = toISODate(col(row, 'Date de fin'));

  byKey.set(`${reference}|${dateDebut}|${dateFin || ''}`, {
    statut: cleanString(col(row, 'Statut')),
    type_promotion: cleanString(col(row, "Type d'opération", 'Type de promotion')),
    produit,
    ean: cleanString(col(row, 'EAN Produit')),
    reference_article: reference,
    date_debut: dateDebut,
    date_fin: dateFin,
    prix_vente_ttc: parseNumber(col(row, 'Prix de vente TTC')),
    nouveau_prix_ttc: parseNumber(col(row, 'Prix Promo TTC')),
    difference: parseNumber(col(row, 'Baisse de prix')),
    compensation_ht: parseNumber(col(row, 'Compensation €HT')),
    date_butoir_declaration: toISODate(col(row, 'Date butoir de déclaration')),
    mise_a_jour: toISODate(col(row, 'Mise à Jour')),
    declaration_sts_dji: cleanString(col(row, 'Déclaration de STS à DJI')),
  });
}

const rows = [...byKey.values()];
if (rows.length === 0) {
  throw new Error('Aucune promotion lue dans le template (' + res.filename + ') : table laissee intacte');
}

return [{
  json: {
    template: res.filename,
    lignes_lues: lignesLues,
    promos_uniques: rows.length,
    doublons_fichier: lignesLues - sansDateDebut.length - rows.length,
    sans_date_debut: sansDateDebut,
    payload: JSON.stringify(rows),
  },
}];
